#include "autoload_ui.h"
void as_ui_fail(struct as_ui_state*s,uint32_t error){if(!s)return;s->report.result=error;s->terminal=1;s->done=0;}
int as_ui_once(struct as_ui_state*s,const struct as_ui_ports*p){if(!s||!p||!p->bind||!p->install)return AS_UI_TERMINAL;if(s->terminal)return AS_UI_TERMINAL;if(s->done)return AS_UI_DONE;s->report.callbacks++;if(!s->report.bound){int rc=p->bind(p->context);if(rc){as_ui_fail(s,(uint32_t)rc);return AS_UI_TERMINAL;}s->report.bound=1;}uint32_t proof=~0u;int rc=p->install(p->context,&proof);if(!rc){if(proof){as_ui_fail(s,AS_UI_BAD_PROOF);return AS_UI_TERMINAL;}s->report.result=0;s->done=1;return AS_UI_DONE;}if(rc==AS_UI_INSTALL_REJECT&&proof==AS_UI_BUSY_PROOF){if(s->report.busy_count<AS_UI_MAX_DEFER){s->report.busy_count++;s->report.result=AS_UI_POWER_PENDING;return AS_UI_DEFER20;}as_ui_fail(s,AS_UI_POWER_TIMEOUT);return AS_UI_TERMINAL;}as_ui_fail(s,(uint32_t)rc);return AS_UI_TERMINAL;}
